                      белки {sum.protein} г{goals && ` из ${goals.protein} г`}, жиры {sum.fat} г{goals && ` из ${goals.fat} г`}, углеводы{" "}
                      {sum.carbs} г{goals && ` из ${goals.carbs} г`}
                    </span>
                  </li>
                );
              })}
